def handle_list_users(params: dict) -> tuple[int, dict]:
    page_str = params.get("page", "1")
    page_size_str = params.get("page_size", "10")

    if not isinstance(page_str, str) or not page_str.isdigit():
        return 400, {"error": "invalid pagination"}
    if not isinstance(page_size_str, str) or not page_size_str.isdigit():
        return 400, {"error": "invalid pagination"}

    page = int(page_str)
    page_size = int(page_size_str)

    if page < 1 or page_size < 1 or page_size > 100:
        return 400, {"error": "invalid pagination"}

    items, total = users.list_users(page, page_size)
    return 200, {
        "users": items,
        "page": page,
        "page_size": page_size,
        "total": total,
    }

